sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {

    var deptObj = api.data.look_up_departments.results;
    var len = deptObj.length;

    var deptArr = [];

    for (var i = 0; i < len; i++) {
        var dept = {id: deptObj[i]._row_data.uniqueValue,
        label: deptObj[i]._row_data.displayValue
        };
        deptArr.push(dept);
    }
    return JSON.stringify(deptArr);
}
